"""Apply approved public notices after rebuilding both language editions."""
from pathlib import Path
from bs4 import BeautifulSoup
R=Path(__file__).resolve().parents[1]
mail='<a href="mailto:thomas.ralf.jaeger@univie.ac.at">thomas.ralf.jaeger@univie.ac.at</a>'
links='<a href="https://docs.github.com/en/pages/getting-started-with-github-pages/what-is-github-pages#data-collection">GitHub Pages</a> · <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub Privacy Statement</a>'
for lang,contact,privacy,access in [('de','impressum','datenschutz','barrierefreiheit'),('en','legal-notice','privacy','accessibility')]:
 de=lang=='de'
 contact_html=(f'<h1>Impressum und Kontakt</h1><section class="section narrow"><h2>Herausgeber und verantwortlich für dieses Angebot</h2><address>Mag. Dr. Thomas Jäger<br>Datenmanager (Professur für Digitales Edieren)<br>Institut für Europäische und Vergleichende Sprach- und Literaturwissenschaft<br>Universitätsring 1, 1010 Wien, Zimmer 02.77<br>{mail}</address><p>Der Editionskompass bietet Orientierung zur Nutzung von Git in wissenschaftlichen Editionsprojekten. Konzeption und Redaktion: Thomas Jäger. Die Projekt- und Perspektivgeschichten sind fiktive Fallbeispiele. KI-Unterstützung bei Redaktion, Übersetzung, Illustration und technischer Umsetzung wird in den Herkunftshinweisen erläutert.</p>' if de else f'<h1>Legal notice and contact</h1><section class="section narrow"><h2>Publisher and person responsible for this website</h2><address>Mag. Dr. Thomas Jäger<br>Data manager, Chair of Digital Scholarly Editing<br>Department of European and Comparative Literature and Language Studies<br>Universitätsring 1, 1010 Vienna, room 02.77<br>{mail}</address><p>Editionskompass offers guidance on using Git in scholarly editing projects. Concept and editorial responsibility: Thomas Jäger. Project and perspective narratives are fictional case studies. The provenance notices describe AI assistance in drafting, translation, illustration and implementation.</p>')
 contact_html+=('<h2 id="licenses">Lizenzen und Herkunft</h2><p>Eigener Programmcode und technische Vorlagen: MIT. Eigene redaktionelle Texte, Lehrmaterialien und bereitgestellte Medien, soweit entsprechende Rechte bestehen: CC BY 4.0. Namensnennung: „Thomas Jäger, Editionskompass“, ergänzt durch Version und Link. Abweichende Rechte Dritter und gemeinfreie Bestandteile behalten ihren Status. Für rein KI-erzeugte Elemente wird kein ausschließliches Urheberrecht behauptet.</p>' if de else '<h2 id="licenses">Licences and provenance</h2><p>Project-authored code and technical templates: MIT. Project-authored editorial content, teaching resources and supplied media, to the extent rights subsist: CC BY 4.0. Attribution: “Thomas Jäger, Editionskompass”, with version and link. Third-party rights and public-domain status remain unchanged. No exclusive copyright is claimed for purely AI-generated elements.</p>')+'<p><a href="https://opensource.org/license/mit">MIT</a> · <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a> · <a href="https://github.com/Jager-Research-Projects/editionskompass/blob/main/RIGHTS.md">Rights and provenance</a></p></section>'
 privacy_html=(f'<h1>Datenschutz</h1><section class="section narrow"><h2>Hosting und Kontakt</h2><p>Verantwortlich für dieses Angebot: Mag. Dr. Thomas Jäger. Kontakt: {mail}; vollständige Anschrift im Impressum.</p><p>Die Website wird über GitHub Pages bereitgestellt. GitHub dokumentiert, dass beim Aufruf IP-Adressen zu Sicherheitszwecken protokolliert und gespeichert werden, unabhängig davon, ob Besuchende bei GitHub angemeldet sind.</p><p>{links}</p><h2>Angaben in den Planern</h2><p>Die Website-Anwendung überträgt Ihre Planungsangaben nicht an einen Server. Strategie-, Datenbank- und Workshop-Planer verwenden den Sitzungsspeicher des eigenen Tabs. Der gewählte Fortschritt der Antipattern Academy kann im lokalen Browserspeicher erhalten bleiben; Löschmöglichkeiten sind im Lernangebot beschrieben. Beim Zusammenstellen eines Workshop-Pakets werden die ausgewählten Materialdateien von dieser Website abgerufen. Externe Informationsquellen werden beim Öffnen der jeweiligen Links besucht. Die Anwendung bindet keine Trackingdienste und keine extern geladenen Schriften ein.</p></section>' if de else f'<h1>Privacy</h1><section class="section narrow"><h2>Hosting and contact</h2><p>Person responsible: Mag. Dr. Thomas Jäger. Contact: {mail}; full postal address in the legal notice.</p><p>This website is hosted using GitHub Pages. GitHub documents that visitors’ IP addresses are logged and stored for security purposes, regardless of whether visitors are signed in to GitHub.</p><p>{links}</p><h2>Planner answers</h2><p>The website application does not transmit your planning answers to a server. The strategy, database and workshop planners use this tab’s session storage. Selected Antipattern Academy progress may remain in local browser storage; the learning activity describes how to clear it. Creating a workshop package retrieves the selected resource files from this website. External sources are visited when their links are opened. The application embeds no tracking services or externally loaded fonts.</p></section>')
 for route,html in [(contact,contact_html),(privacy,privacy_html)]:
  path=R/'dist'/lang/route/'index.html';s=BeautifulSoup(path.read_text(encoding='utf-8'),'html.parser');main=s.find('main');main.clear();main.append(BeautifulSoup(html,'html.parser'));path.write_text(str(s),encoding='utf-8')
 path=R/'dist'/lang/access/'index.html';s=BeautifulSoup(path.read_text(encoding='utf-8'),'html.parser');s.h1.string='Hinweise zur Barrierefreiheit' if de else 'Accessibility information'
 for p in s.select('main p'):
  if ('Screenreader' in p.get_text() or 'screen-reader' in p.get_text()):
   p.string=('Geprüfter Umfang und bekannte Grenzen sind im aktuellen Prüfprotokoll dokumentiert. Eine vollständige manuelle Screenreader-Prüfung und eine formale Konformitätsbewertung sind noch nicht abgeschlossen. Diese Hinweise behaupten keine vollständige gesetzliche Konformität.' if de else 'The current test report describes the checks performed and known limitations. A full manual screen-reader assessment and formal conformance assessment are still outstanding. This information does not claim full statutory conformance.')
 path.write_text(str(s),encoding='utf-8')
